
import { Rule, RuleTester, SourceCode } from "eslint";
import { Node as ESTreeNode, SourceLocation } from "estree";


// ── CSN location ────────────────────────────────────────────────────────────

export namespace CSN {
    export interface Location {
        file: string;
        line: number;
        col: number;
    }
}


// ── CSN node / definition ───────────────────────────────────────────────────

/** A single node in a (linked) CSN model — entity, element, service, action, etc. */
export type CSNNode = {
    name: string;
    kind?: string;
    type?: string;
    $location?: CSN.Location;
    parent?: CSNNode;
    elements?: Record<string, CSNNode>;
    actions?: Record<string, CSNNode>;
    params?: Record<string, CSNNode>;
    keys?: Record<string, CSNNode>;
    target?: string;
    _target?: { elements: Record<string, CSNNode> };
    cardinality?: { max?: '*' | number };
    query?: { SET?: { args: any[] }; SELECT?: { columns?: any[]; from: { ref: string[] } } };
    projection?: { columns?: any[]; from: { ref: string[] } };
    annotate?: unknown;
    /** Linked-model reflector method */
    is?: (kind: string) => boolean;
    /** Catch-all for CDS annotation properties (@restrict, @requires, etc.) */
    [key: string]: any;
};


// ── CSN model ───────────────────────────────────────────────────────────────

/** A linked or parsed CSN model returned by context.getModel() */
export type CSNModel = {
    definitions: Record<string, any>;
    messages?: any[];
    /** Iterate over all definitions */
    forall: (callback: (d: CSNNode) => void) => void;
    /** Iterate over definitions of a given kind */
    foreach: (kind: string, callback: (d: CSNNode) => void) => void;
};

/**
 * @deprecated Use CSNModel. This alias exists only to avoid breaking existing
 * usages of `import('../types').CSN` as a value type.
 */
export type CSN = CSNModel;


// ── @restrict entry ─────────────────────────────────────────────────────────

export type RestrictEntry = {
    grant?: string | string[];
    to?: string | string[] | null;
    where?: string | object | null;
};


// ── Rule context ─────────────────────────────────────────────────────────────

export type SourceLoc = { start: { line: number; column: number }; end: { line: number; column: number } };

export interface CDSRuleContext extends Rule.RuleContext {
    options: any[];
    sourceCode: SourceCode;
    getModel: () => CSNModel | undefined;
    getLocation: (name: string | undefined, obj: CSNNode, model?: CSNModel) => SourceLoc;
    getNode: (obj?: CSNNode) => ESTreeNode;
    getEnvironment: () => Record<string, any> | undefined;
    getRootPath: () => string | undefined;
    report: (descriptor: CDSRuleReport) => void;
}

export interface CDSRuleMetaData extends Rule.RuleMetaData {
    model?: "parsed" | "inferred" | "none";
}

export type CDSRuleReport = Rule.ReportDescriptor & {
    loc?: SourceLoc;
    file?: string;
};


// ── Rule definition ──────────────────────────────────────────────────────────

export interface CDSRule {
    meta: CDSRuleMetaData;
    create: (context: CDSRuleContext) => void;
}


// ── Rule tester ──────────────────────────────────────────────────────────────

export interface CDSTestCaseError extends RuleTester.TestCaseError {
    message: string | RegExp;
}

export interface CDSRuleTestOpts {
    /** specifies __dirname */
    root: string;
    /** requires your rule .js here */
    rule?: string;
    /** filename ('schema.cds' for model, 'package.json' for env) */
    filename: string;
    /** resolves cds parser path */
    parser?: string;
    /** list of errors from ESLint's [RuleTester](https://eslint.org/docs/developer-guide/nodejs-api#ruletester) */
    errors: CDSTestCaseError[];
    /** optional rule options */
    options?: any;
}


// ── Misc ─────────────────────────────────────────────────────────────────────

export type ConfigOverrideFiles = string[]

export type Definition = {
    name: string,
    elements?: Record<string, unknown>
}

export type RuleContext = {
    sourceCode: {
        lines: string[];
        getText: (node?: ESTreeNode) => string;
        getLocFromIndex: (index: number) => { line: number; column: number };
        getAllComments: () => any[];
    };
    filename: string;
    report: Function;
}

export namespace AST {
    export interface Program {}
}
